const owner = $env.GITHUB_OWNER;
const repo = $env.GITHUB_REPO;
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const githubToken = $env.GITHUB_TOKEN;
const anthropicKey = $env.ANTHROPIC_API_KEY;
const discordWebhookUrl = $env.DISCORD_WEBHOOK_URL;
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

if (!owner || !repo || !anthropicKey || !discordWebhookUrl) {
  throw new Error('Set GITHUB_OWNER, GITHUB_REPO, ANTHROPIC_API_KEY, and DISCORD_WEBHOOK_URL before running this workflow.');
}

const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const startIso = start.toISOString();
const endIso = end.toISOString();
const startDate = startIso.slice(0, 10);
const endDate = endIso.slice(0, 10);

const githubHeaders = {
  Accept: 'application/vnd.github+json',
  'User-Agent': 'n8n-claude-weekly-summary'
};
if (githubToken) githubHeaders.Authorization = `Bearer ${githubToken}`;

async function github(path, qs = {}) {
  return await httpRequest({
    method: 'GET',
    uri: `https://api.github.com${path}`,
    headers: githubHeaders,
    qs,
    json: true
  });
}

const commits = await github(`/repos/${owner}/${repo}/commits`, {
  since: startIso,
  until: endIso,
  per_page: 100
});

const closedIssues = await github('/search/issues', {
  q: `repo:${owner}/${repo} is:issue is:closed closed:${startDate}..${endDate}`,
  per_page: 100
});

const mergedPrs = await github('/search/issues', {
  q: `repo:${owner}/${repo} is:pr is:merged merged:${startDate}..${endDate}`,
  per_page: 100
});

const commitLines = commits.map((commit) => `- ${commit.commit.message.split('\n')[0]} (${commit.sha.slice(0, 7)})`).join('\n') || '- No commits found';
const issueLines = (closedIssues.items || []).map((issue) => `- #${issue.number} ${issue.title}`).join('\n') || '- No closed issues found';
const prLines = (mergedPrs.items || []).map((pr) => `- #${pr.number} ${pr.title}`).join('\n') || '- No merged PRs found';

const prompt = `Write a concise weekly engineering summary in ${language === 'FR' ? 'French' : 'English'} for ${owner}/${repo}.\n\nPeriod: ${startDate} to ${endDate}\n\nCommits:\n${commitLines}\n\nClosed issues:\n${issueLines}\n\nMerged PRs:\n${prLines}\n\nMake it narrative, useful for a team update, and avoid hype.`;

const claude = await httpRequest({
  method: 'POST',
  uri: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': anthropicKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1200,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ]
  },
  json: true
});

const summary = claude.content?.[0]?.text || 'Claude returned no summary text.';

return [
  {
    json: {
      owner,
      repo,
      language,
      startDate,
      endDate,
      commitCount: commits.length,
      closedIssueCount: closedIssues.total_count || 0,
      mergedPrCount: mergedPrs.total_count || 0,
      summary,
      discordWebhookUrl
    }
  }
];
